for (const [name, id] of Object.entries(REVERSE_STATIONS_MAP)) {
  STATIONS_MAP[id] = name;
}

export const normalizeStation = (name: string): string => {
  if (!name) return '';
  return name.toString().trim().toLowerCase();
};

export const getStationId = (name: string): number | null => {
  const normalized = normalizeStation(name);
  const originalName = Object.keys(REVERSE_STATIONS_MAP).find(k => normalizeStation(k) === normalized);
  return originalName ? REVERSE_STATIONS_MAP[originalName] : null;
};
